211	/**
212	 * @brief   System formatted output function.
213	 * @details This function implements a minimal @p vprintf()-like functionality
214	 *          with output on a @p BaseSequentialStream.
215	 *          The general parameters format is: %[-][width|*][.precision|*][l|L]p.
216	 *          The following parameter types (p) are supported:
217	 *          - <b>x</b> hexadecimal integer.
218	 *          - <b>X</b> hexadecimal long.
219	 *          - <b>o</b> octal integer.
220	 *          - <b>O</b> octal long.
221	 *          - <b>d</b> decimal signed integer.
222	 *          - <b>D</b> decimal signed long.
223	 *          - <b>u</b> decimal unsigned integer.
224	 *          - <b>U</b> decimal unsigned long.
225	 *          - <b>c</b> character.
226	 *          - <b>s</b> string.
227	 *          .
228	 *
229	 * @param[in] chp       pointer to a @p BaseSequentialStream implementing object
230	 * @param[in] fmt       formatting string
231	 * @param[in] ap        list of parameters
232	 * @return              The number of bytes that would have been
233	 *                      written to @p chp if no stream error occurs
234	 *
235	 * @api
236	 */
237	#define IS_LONG             1
238	#define LEFT_ALIGN          2
239	#define POSITIVE            4
240	#define NEGATIVE            8
241	#define PAD_ZERO            16
242	#define PLUS_SPACE          32
243	#define DEFAULT_PRESCISION  64
244	
245	int chvprintf(BaseSequentialStream *chp, const char *fmt, va_list ap) {
246	  char *p, *s, c, filler=' ';
247	  int precision, width;
248	  int n = 0;
249	  uint32_t  state;
250	  union {
251	      uint32_t u;
252	      int32_t  l;
253	      float    f;
254	  }value;
255	#if CHPRINTF_USE_FLOAT
256	  char tmpbuf[2*MAX_FILLER + 1];
257	#else
258	  char tmpbuf[MAX_FREQ_PRESCISION + 1];
259	#endif
260	
261	  while (true) {
262	    c = *fmt++;
263	    if (c == 0)
264	      return n;
265	    if (c != '%') {
266	      streamPut(chp, (uint8_t)c);
267	      n++;
268	      continue;
269	    }
270	    // Parse %[flags][width][.precision][length]type
271	    p = tmpbuf;
272	    s = tmpbuf;
273	    state = 0;
274	    width = 0;
275	    precision = 0;
276	
277	    // Get [flags], support:
278	    // '-' Left-align the output of this placeholder. (The default is to right-align the output.)
279	    // '+' Prepends a  plus for positive signed-numeric types. positive = '+', negative = '-'.
280	    // ' ' Prepends a space for positive signed-numeric types. positive = ' ', negative = '-'. This flag is ignored if the + flag exists.
281	    // '0' When the 'width' option is specified, prepends zeros for numeric types. (The default prepends spaces.)
282	    while (true){
283	      if (*fmt == '-')
284	        state|=LEFT_ALIGN;
285	      else if (*fmt == '+')
286	        state|=POSITIVE;
287	      else if (*fmt == '0')
288	        state|=PAD_ZERO;
289	#ifdef CHPRINTF_USE_SPACE_FLAG
290	      else if (*fmt == ' ')
291	        state|=PLUS_SPACE;
292	#endif
293	      else
294	        break;
295	      fmt++;
296	    }
297	    // Get [width] - The Width field specifies a minimum number of characters to output
298	    // if set *, get width as argument
299	    while (true) {
300	      c = *fmt++;
301	      if (c >= '0' && c <= '9')
302	        c -= '0';
303	      else if (c == '*')
304	        c = va_arg(ap, int);
305	      else
306	        break;
307	      width = width * 10 + c;
308	    }
309	    // Get [.precision]
310	    if (c == '.') {
311	      while (true) {
312	        c = *fmt++;
313	        if (c >= '0' && c <= '9')
314	          c -= '0';
315	        else if (c == '*')
316	          c = va_arg(ap, int);
317	        else
318	           break;
319	        precision = precision * 10 + c;
320	      }
321	    }
322	    else
323	      state|=DEFAULT_PRESCISION;
324	    //Get [length]
325	    /*
326	    if (c == 'l' || c == 'L') {
327	      state|=IS_LONG;
328	      if (*fmt)
329	        c = *fmt++;
330	    }
331	    else if ((c >= 'A') && (c <= 'Z'))
332	        state|=IS_LONG;
333	    */
334	    // Parse type
335	    switch (c) {
336	    case 'c':
337	      state&=~PAD_ZERO;
338	      *p++ = va_arg(ap, int);
339	      break;
340	    case 's':
341	      state&=~PAD_ZERO;
342	      if ((s = va_arg(ap, char *)) == 0)
343	        s = "(null)";
344	      if (state&DEFAULT_PRESCISION)
345	        precision = 32767;
346	      for (p = s; *p && (--precision >= 0); p++)
347	        ;
348	      break;
349	    case 'D':
350	    case 'd':
351	    case 'I':
352	    case 'i':/*
353	      if (state & IS_LONG)
354	        value.l = va_arg(ap, long);
355	      else*/
356	        value.l = va_arg(ap, uint32_t);
357	      if (value.l < 0) {
358	        state|=NEGATIVE;
359	        *p++ = '-';
360	        value.l = -value.l;
361	      }
362	      else if (state & POSITIVE)
363	        *p++ = '+';
364	#ifdef CHPRINTF_USE_SPACE_FLAG
365	      else if (state & PLUS_SPACE)
366	        *p++ = ' ';
367	#endif
368	      p = long_to_string_with_divisor(p, value.l, 10, 0);
369	      break;
370	    case 'q':
371	      value.u = va_arg(ap, uint32_t);
372	      p=ulong_freq(p, value.u, precision);
373	      break;
374	#if CHPRINTF_USE_FLOAT
375	    case 'F':
376	    case 'f':
377	      value.f = va_arg(ap, double);
378	      if (value.f < 0) {
379	        state|=NEGATIVE;
380	        *p++ = '-';
381	        value.f = -value.f;
382	      }
383	      else if (state & POSITIVE)
384	        *p++ = '+';
385	#ifdef CHPRINTF_USE_SPACE_FLAG
386	      else if (state & PLUS_SPACE)
387	        *p++ = ' ';
388	#endif
389	      if (value.f == INFINITY){
390	        *p++ = 0x19;
391	        break;
392	      }
393	      p = (c=='F') ? ftoaS(p, value.f, precision) : ftoa(p, value.f, state&DEFAULT_PRESCISION ? FLOAT_PRECISION : precision);
394	      break;
395	#endif
396	    case 'X':
397	    case 'x':
398	      c = 16;
399	      goto unsigned_common;
400	    case 'U':
401	    case 'u':
402	      c = 10;
403	      goto unsigned_common;
404	    case 'O':
405	    case 'o':
406	      c = 8;
407	unsigned_common:/*
408	      if (state & IS_LONG)
409	        value.u = va_arg(ap, unsigned long);
410	      else*/
411	        value.u = va_arg(ap, uint32_t);
412	      p = long_to_string_with_divisor(p, value.u, c, 0);
413	      break;
414	    default:
415	      *p++ = c;
416	      break;
417	    }
418	    // Now need print buffer s[{sign}XXXXXXXXXXXX]p and align it on width
419	    // Check filler width (if buffer less then width) and prepare filler if need fill
420	    if ((width -=(int)(p - s)) < 0)
421	      width = 0;
422	    else
423	      filler = (state&PAD_ZERO) ? '0' : ' ';
424	    // if left align, put sign digit, and fill
425	    // [{sign}ffffffXXXXXXXXXXXX]
426	    if (!(state&LEFT_ALIGN)) {
427	      // Put '+' or '-' or ' ' first if need
428	      if ((state&(NEGATIVE|POSITIVE|PLUS_SPACE)) && (state&PAD_ZERO)) {
429	        streamPut(chp, (uint8_t)*s++);
430	        n++;
431	      }
432	      // fill from left
433	      while (width){
434	        streamPut(chp, (uint8_t)filler);
435	        n++;
436	        width--;
437	      }
438	    }
439	    // put data
440	    while (s < p) {
441	      streamPut(chp, (uint8_t)*s++);
442	      n++;
443	    }
444	    // Put filler from right (if need)
445	    while (width) {
446	      streamPut(chp, (uint8_t)filler);
447	      n++;
448	      width--;
449	    }
450	  }
451	}
